// Keep product rows only (summary rows are free metadata) and map to sheet columns.
const today = new Date().toISOString().slice(0, 10);
const out = [];
for (const { json: r } of $input.all()) {
  if (r.recordType && r.recordType !== 'product') continue;
  const changed = r.isNewInTop === true || (r.rankChange ?? 0) !== 0 || (r.priceChange ?? 0) !== 0;
  // First run has no history (all change fields null): rows are written once as the baseline.
  const baseline = r.previousRank == null && r.previousPrice == null && r.isNewInTop == null;
  if (!changed && !baseline) continue;
  out.push({ json: {
    date: today,
    keyword: r.keyword,
    rank: r.rank,
    previousRank: r.previousRank,
    rankChange: r.rankChange,
    price: r.price,
    previousPrice: r.previousPrice,
    priceChange: r.priceChange,
    isNewInTop: r.isNewInTop,
    title: r.title,
    mallName: r.mallName,
    productId: r.productId,
    url: r.url,
  }});
}
return out;
